164	    /// Nonblocking latest-plan admission. QueueFull means retry the same pinned
165	    /// plan after a worker notification. No executable work or argv scans occur.
166	    pub fn try_install(&self, plan: &Arc<AutostartPlan>) -> Result<(), Error> {
167	        let mut c = self
168	            .shared
169	            .control
170	            .lock()
171	            .unwrap_or_else(|e| e.into_inner());
172	        if c.closed || self.thread.as_ref().is_none_or(|t| t.is_finished()) {
173	            return Err(Error::Stopped);
174	        }
175	        if plan.generation <= c.latest {
176	            return Err(Error::Invalid("autostart generation is stale".into()));
177	        }
178	        if c.pending.is_some() && c.discard.is_some() {
179	            return Err(Error::QueueFull);
180	        }
181	        c.latest = plan.generation;
182	        if let Some(old) = c.pending.replace(plan.clone()) {
183	            c.discard = Some(old);
184	        }
185	        self.shared.changed.notify_one();
186	        Ok(())
187	    }
