198	        self.shared
199	            .control
200	            .lock()
201	            .unwrap_or_else(|e| e.into_inner())
202	            .snapshot
203	            .take()
204	    }
205	    /// Seals admission without dropping plans, killing or waiting on dispatch.
206	    pub fn stop(&self) {
207	        let mut c = self
208	            .shared
209	            .control
210	            .lock()
211	            .unwrap_or_else(|e| e.into_inner());
212	        c.closed = true;
213	        self.shared.changed.notify_one();
214	    }
215	    pub fn shutdown(&mut self) -> io::Result<()> {
216	        self.stop();
