294	fn publish(shared: &Shared, slots: &[Slot], progress: &Progress, notify: &impl Fn()) {
295	    let mut snapshot = AutostartSnapshot {
296	        requested_generation: progress.observed,
297	        active_generation: progress.active,
298	        active_complete: progress.active_complete,
299	        retained_argv_bytes: slots.iter().map(|s| s.bytes).sum(),
300	        settled: progress.settled,
301	        closed: false,
302	        error: progress.error,
303	        entries: slots.iter().map(|s| s.view.clone()).collect(),
304	    };
305	    let old = {
306	        let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
307	        snapshot.closed = c.closed;
