313	fn reap(slots: &mut [Slot]) -> bool {
314	    let mut changed = false;
315	    for slot in slots {
316	        if let Some(child) = slot.child.as_mut() {
317	            match child.try_wait() {
318	                Ok(Some(status)) => {
319	                    slot.exited(status);
320	                    slot.child.take();
321	                    changed = true;
322	                }
323	                Ok(None) => (),
324	                Err(error) => {
325	                    if slot.view.error != Some("owned child reaping failed")
326	                        || slot.view.errno != error.raw_os_error()
327	                    {
328	                        changed = true;
329	                    }
330	                    slot.view.error = Some("owned child reaping failed");
331	                    slot.view.state = "ownership-error";
332	                    slot.view.errno = error.raw_os_error();
333	                }
334	            }
335	        }
336	    }
337	    changed
338	}
339	/// Broadcast TERM before a common grace interval, then retire remaining owned
340	/// children. No waitpid(-1), process-group signalling or descendant claim.
341	fn retire(slots: &mut [Slot], indices: &[usize]) {
342	    for &i in indices {
343	        if let Some(child) = slots[i].child.as_mut() {
344	            match child.try_wait() {
345	                Ok(Some(status)) => slots[i].exited(status),
346	                Ok(None) => {
347	                    // SAFETY: this exclusive unreaped Child keeps its PID from
348	                    // reuse. No external reaper may compete with this owner.
349	                    if unsafe { libc::kill(child.id() as libc::pid_t, libc::SIGTERM) } != 0 {
350	                        slots[i].view.error = Some("owned child termination failed");
351	                        slots[i].view.errno = io::Error::last_os_error().raw_os_error();
352	                    }
353	                }
354	                Err(error) => {
355	                    slots[i].view.error = Some("owned child reaping failed");
356	                    slots[i].view.errno = error.raw_os_error();
357	                }
358	            }
359	        }
360	    }
361	    let deadline = Instant::now() + GRACE;
362	    while Instant::now() < deadline {
363	        let mut live = false;
364	        for &i in indices {
365	            if let Some(child) = slots[i].child.as_mut() {
366	                match child.try_wait() {
367	                    Ok(Some(status)) => {
368	                        slots[i].exited(status);
369	                        slots[i].child.take();
370	                    }
371	                    Ok(None) => live = true,
372	                    Err(_) => {
373	                        live = true;
374	                    }
375	                }
376	            }
377	        }
378	        if !live {
379	            break;
380	        }
381	        thread::sleep(Duration::from_millis(2));
382	    }
383	    for &i in indices {
384	        if let Some(mut child) = slots[i].child.take() {
385	            match child.try_wait() {
386	                Ok(Some(status)) => slots[i].exited(status),
387	                Ok(None) => {
388	                    let _ = child.child.kill();
389	                    match child.wait() {
390	                        Ok(status) => slots[i].exited(status),
391	                        Err(error) => {
392	                            slots[i].view.error = Some("owned child retirement failed");
393	                            slots[i].view.errno = error.raw_os_error();
394	                        }
395	                    }
396	                }
397	                Err(error) => {
398	                    slots[i].view.error = Some("owned child retirement failed");
399	                    slots[i].view.errno = error.raw_os_error();
400	                }
401	            }
402	        }
403	        slots[i].view.pid = None;
404	    }
405	}
406	fn run(shared: Arc<Shared>, notify: impl Fn()) {
407	    let mut slots: Vec<Slot> = Vec::new();
408	    let mut progress = Progress {
409	        settled: true,
410	        ..Progress::default()
411	    };
412	    loop {
413	        let (plan, discard, should_reap, closed) = {
414	            let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
415	            while !c.closed && c.pending.is_none() && c.discard.is_none() && !c.reap {
416	                c = shared.changed.wait(c).unwrap_or_else(|e| e.into_inner());
417	            }
418	            let values = (c.pending.take(), c.discard.take(), c.reap, c.closed);
419	            c.reap = false;
420	            values
421	        };
422	        let discarded = discard.is_some();
423	        drop(discard);
424	        if discarded {
425	            notify();
426	        }
427	        if closed {
428	            break;
429	        }
430	        if should_reap && reap(&mut slots) {
431	            publish(&shared, &slots, &progress, &notify);
432	        }
433	        let Some(plan) = plan else {
434	            continue;
435	        };
436	        if !current(&shared, plan.generation) {
437	            continue;
438	        }
439	        progress.observed = Some(plan.generation);
440	        let added = plan
441	            .entries
442	            .iter()
443	            .filter(|entry| !slots.iter().any(|s| s.identity == entry.identity))
444	            .count();
445	        let mut bytes = 0usize;
446	        for slot in &slots {
447	            if let Some(entry) = plan.entries.iter().find(|e| e.identity == slot.identity) {
448	                bytes += if slot.needs_start(entry) {
449	                    // Any prefix can survive supersession. Account for both
450	                    // shrinking old histories and growing replacements.
451	                    slot.bytes.max(entry.bytes)
452	                } else {
453	                    slot.bytes
454	                };
455	            }
456	        }
457	        bytes += plan
458	            .entries
459	            .iter()
460	            .filter(|e| !slots.iter().any(|s| s.identity == e.identity))
461	            .map(|e| e.bytes)
462	            .sum::<usize>();
463	        if slots.len() + added > MAX_AUTOSTART_IDENTITIES || bytes > MAX_AUTOSTART_HISTORY_BYTES {
464	            progress.error = Some("autostart session identity or retained argv budget exceeded");
465	            progress.settled = true;
466	            publish(&shared, &slots, &progress, &notify);
467	            continue;
468	        }
469	        for entry in &plan.entries {
470	            if !slots.iter().any(|s| s.identity == entry.identity) {
471	                slots.push(Slot::new(slots.len(), entry.identity.clone()));
472	            }
473	        }
474	        let stop: Vec<_> = slots
475	            .iter()
476	            .enumerate()
477	            .filter_map(|(i, s)| {
478	                let desired = plan.entries.iter().find(|e| e.identity == s.identity);
479	                (s.child.is_some() && desired.is_none_or(|entry| s.needs_start(entry))).then_some(i)
480	            })
481	            .collect();
482	        progress.active = Some(plan.generation);
483	        progress.error = None;
484	        progress.settled = false;
485	        progress.active_complete = false;
486	        // A superseding plan can arrive during retirement. Preserve the need
487	        // to restart a deliberately retired child even if it restores argv.
488	        for &i in &stop {
489	            slots[i].restart_pending = true;
490	        }
491	        retire(&mut slots, &stop);
492	        for slot in &mut slots {
493	            if !plan.entries.iter().any(|e| e.identity == slot.identity) {
494	                slot.present = false;
495	                slot.restart_pending = false;
496	                slot.history = None;
497	                slot.bytes = 0;
498	                slot.view.desired = false;
499	                slot.view.index = None;
500	                slot.view.change_deferred = false;
501	                slot.view.state = "removed";
502	            }
503	        }
504	        publish(&shared, &slots, &progress, &notify);
505	        let mut complete = true;
506	        for (index, entry) in plan.entries.iter().enumerate() {
507	            if !current(&shared, plan.generation) {
508	                complete = false;
509	                break;
510	            }
511	            let slot = slots
512	                .iter_mut()
513	                .find(|s| s.identity == entry.identity)
514	                .expect("reserved identity");
515	            let start = slot.needs_start(entry);
516	            slot.present = true;
517	            slot.view.desired = true;
518	            slot.view.index = Some(index);
519	            slot.view.change_deferred = !start
520	                && slot
521	                    .history
522	                    .as_ref()
523	                    .is_some_and(|h| h.as_ref() != entry.argv.as_ref());
524	            if !start {
525	                if slot.history.is_none() {
526	                    slot.view.state = "once-suppressed";
527	                }
528	                continue;
529	            }
530	            let Some(attempts) = slot.view.attempts.checked_add(1) else {
531	                slot.view.error = Some("autostart attempt counter exhausted");
532	                continue;
533	            };
534	            slot.restart_pending = false;
535	            slot.history = Some(entry.argv.clone());
536	            slot.bytes = entry.bytes;
537	            slot.view.attempts = attempts;
538	            slot.view.error = None;
539	            slot.view.errno = None;
540	            slot.view.exit_code = None;
541	            slot.view.exit_signal = None;
542	            let job = SpawnJob {
543	                operation: plan.generation,
544	                argv: entry.argv.as_ref().clone(),
545	                wayland_display: plan.display.clone(),
546	                ipc_socket: plan.ipc.clone(),
547	            };
548	            match crate::launch(job) {
549	                Ok(child) => {
550	                    slot.view.starts = slot
551	                        .view
552	                        .starts
553	                        .checked_add(1)
554	                        .expect("starts bounded by attempts");
555	                    slot.view.pid = Some(child.id());
556	                    slot.view.state = "running";
557	                    slot.child = Some(child);
558	                }
559	                Err(error) => {
560	                    slot.view.state = "failed";
561	                    slot.view.pid = None;
562	                    slot.view.error = Some("autostart executable could not be started");
563	                    slot.view.errno = error.raw_os_error();
564	                }
565	            }
566	            reap(&mut slots);
567	            publish(&shared, &slots, &progress, &notify);
568	        }
569	        progress.settled = complete;
570	        progress.active_complete = complete;
571	        publish(&shared, &slots, &progress, &notify);
572	    }
573	    let indices: Vec<_> = (0..slots.len()).collect();
574	    retire(&mut slots, &indices);
575	    for s in &mut slots {
576	        s.view.state = "stopped";
577	        s.view.pid = None;
578	        s.history = None;
579	        s.bytes = 0;
580	    }
581	    progress.settled = true;
582	    publish(&shared, &slots, &progress, &notify);
583	    let (pending, discard) = {
584	        let mut c = shared.control.lock().unwrap_or_else(|e| e.into_inner());
585	        (c.pending.take(), c.discard.take())
586	    };
587	    drop((pending, discard));
588	}
